  "sem registro": ["no entry yet", "sin registro", "暂无记录", "कोई रिकॉर्ड नहीं", "rien noté"],
  "semana seguida": ["week in a row", "semana seguida", "周连续训练", "हफ़्ता लगातार", "semaine d'affilée"],
  "semanas seguidas": ["weeks in a row", "semanas seguidas", "周连续训练", "हफ़्ते लगातार", "semaines d'affilée"],
